#include <iostream>
#include <vector>
#include <algorithm>
#include <limits>

using namespace std;

struct Point {
    int x, y;
};

int main() {
    int N;
    cin >> N;
    vector<Point> mackerels(N);
    vector<Point> sardines(N);
    for (int i = 0; i < N; ++i) {
        cin >> mackerels[i].x >> mackerels[i].y;
    }
    for (int i = 0; i < N; ++i) {
        cin >> sardines[i].x >> sardines[i].y;
    }

    // Compute initial bounding box for mackerels
    int x_min_m = numeric_limits<int>::max();
    int x_max_m = numeric_limits<int>::min();
    int y_min_m = numeric_limits<int>::max();
    int y_max_m = numeric_limits<int>::min();
    for (const auto& p : mackerels) {
        x_min_m = min(x_min_m, p.x);
        x_max_m = max(x_max_m, p.x);
        y_min_m = min(y_min_m, p.y);
        y_max_m = max(y_max_m, p.y);
    }

    // Compute initial a and b
    int a_initial = 0;
    int b_initial = 0;
    for (const auto& p : mackerels) {
        if (x_min_m <= p.x && p.x <= x_max_m && y_min_m <= p.y && p.y <= y_max_m) {
            a_initial++;
        }
    }
    for (const auto& p : sardines) {
        if (x_min_m <= p.x && p.x <= x_max_m && y_min_m <= p.y && p.y <= y_max_m) {
            b_initial++;
        }
