// Function to count points in a rectangle
int count_points_in_rectangle(vector<pair<int, int>> &points, int x1, int x2, int y1, int y2) {
    auto left = lower_bound(points.begin(), points.end(), make_pair(x1, 0));
    auto right = upper_bound(points.begin(), points.end(), make_pair(x2, INT_MAX));
    int count = 0;
    for (auto it = left; it != right; ++it) {
        if (it->second >= y1 && it->second <= y2) {
            count++;
        }
    }
    return count;
}

