#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
};

vector<Point> mackerels;
vector<Point> sardines;

int count_in_rect(const vector<Point>& points, int x1, int x2, int y1, int y2) {
    int count = 0;
    for (const auto& p : points) {
        if (p.x >= x1 && p.x <= x2 && p.y >= y1 && p.y <= y2) {
            count++;
        }
    }
    return count;
}

int main() {
    int N;
    cin >> N;
    mackerels.resize(N);
    sardines.resize(N);
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        mackerels[i].x = x;
        mackerels[i].y = y;
    }
    for (int i = 0; i < N; ++i) {
        int x, y;
        cin >> x >> y;
        sardines[i].x = x;
        sardines[i].y = y;
    }

    // Find initial rectangle for mackerels
    int x1 = INT_MAX, x2 = INT_MIN;
    int y1 = INT_MAX, y2 = INT_MIN;
    for (const auto& p : mackerels) {
        x1 = min(x1, p.x);
        x2 = max(x2, p.x);
        y1 = min(y1, p.y);
        y2 = max(y2, p.y);
    }

    int best_diff = -1;
    int best_x1 = x1, best_x2 = x2, best_y1 = y1, best_y2 = y2;

